// billing.ts
// Version A
function computeTotal(order, type) {
  let subtotal = order.items.reduce((s, i) => s + i.price, 0);
  if (type === 'retail') subtotal = Math.round(subtotal * 1.08);
  if (type === 'wholesale') subtotal = Math.round(subtotal * 0.06);
  return subtotal;
}

// Version B
function roundToCents(amount) { return Math.round(amount); }
function computeRetailTotal(order) {
  const subtotal = order.items.reduce((s, i) => s + i.price, 0);
  return roundToCents(subtotal * 1.08);
}
function computeWholesaleTotal(order) {
  const subtotal = order.items.reduce((s, i) => s + i.price, 0);
  return roundToCents(subtotal * 0.06);
}
